@IsTest private class OwnedKnowledgeLanguageTest {
 @IsTest static void observe() {
  Map<String,Object> seen=new Map<String,Object>();
  User principal=[SELECT Id,UserPermissionsKnowledgeUser FROM User WHERE Id=:UserInfo.getUserId()];
  try{principal.UserPermissionsKnowledgeUser=true;update principal;seen.put('knowledgeUser',true);}catch(Exception e){seen.put('knowledgeUserError',e.getTypeName());}
  System.runAs(principal){
   seen.put('createable',Knowledge__kav.Language.getDescribe().isCreateable());seen.put('updateable',Knowledge__kav.Language.getDescribe().isUpdateable());
   Knowledge__kav article=new Knowledge__kav(Title='Owned Knowledge',UrlName='owned-knowledge-probe',Language='en_US');
   try {
    Database.insert(article,AccessLevel.SYSTEM_MODE);seen.put('inserted',article.Id!=null);
    Knowledge__kav loaded=[SELECT Language,Title FROM Knowledge__kav WHERE Id=:article.Id WITH SYSTEM_MODE];seen.put('language',loaded.Language);
    try{Database.update(new Knowledge__kav(Id=article.Id,Language='en_US'),AccessLevel.SYSTEM_MODE);seen.put('sameLanguageUpdate','returned');}catch(DmlException e){seen.put('sameLanguageUpdate',String.valueOf(e.getDmlStatusCode(0)));}
    try{Database.update(new Knowledge__kav(Id=article.Id,Title='Changed Owned Knowledge'),AccessLevel.SYSTEM_MODE);seen.put('titleUpdate','returned');}catch(DmlException e){seen.put('titleUpdate',String.valueOf(e.getDmlStatusCode(0)));}
   }catch(DmlException e){seen.put('insertError',String.valueOf(e.getDmlStatusCode(0)));seen.put('insertMessage',e.getDmlMessage(0));}
  }
  System.assert(false,'OWNED_KNOWLEDGE|'+JSON.serialize(seen));
 }
}

